CREATE OR REPLACE FUNCTION public.vip_reorder_guides(p_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record;
begin
  for r in select o.id, o.n, g.programme_id from unnest(coalesce(p_ids, '{}')) with ordinality as o(id, n)
